namespace _2026WebAPI_01.Repositories;

public sealed class CategoryRepository : BaseRepository, ICategoryRepository
{
    public CategoryRepository(IStoredProcedureExecutor storedProcedureExecutor)
        : base(storedProcedureExecutor)
    {
    }

    public async Task<PagedResult<CategoryResponseDto>> SearchAsync(
        CategorySearchRequest request,
        CancellationToken cancellationToken = default)
    {
        var items = await QueryAsync<CategoryListItemDto>(
            StoredProcedureNames.Category.Search,
            new
            {
                Keyword = request.Keyword,
                ParentCategoryID = request.ParentCategoryID,
                IsActived = request.IsActived,
                PageIndex = request.PageNumber,
                PageSize = request.PageSize
            },
            cancellationToken);

        var totalRecords = items.FirstOrDefault()?.TotalRecord ?? 0;

        return new PagedResult<CategoryResponseDto>
        {
            Items = items.Select(MapToResponse).ToArray(),
            PageNumber = request.PageNumber,
            PageSize = request.PageSize,
            TotalRecords = totalRecords
        };
    }

    public Task<CategoryResponseDto?> GetByIdAsync(
        long categoryId,
        CancellationToken cancellationToken = default)
    {
        return QuerySingleOrDefaultAsync<CategoryResponseDto>(
            StoredProcedureNames.Category.GetById,
            new { CategoryID = categoryId },
            cancellationToken);
    }

    public Task<CategoryResponseDto?> CreateAsync(
        CategoryCreateRequest request,
        CancellationToken cancellationToken = default)
    {
        return QuerySingleOrDefaultAsync<CategoryResponseDto>(
            StoredProcedureNames.Category.Create,
            request,
            cancellationToken);
    }

    public Task<CategoryResponseDto?> UpdateAsync(
        long categoryId,
        CategoryUpdateRequest request,
        CancellationToken cancellationToken = default)
    {
        return QuerySingleOrDefaultAsync<CategoryResponseDto>(
            StoredProcedureNames.Category.Update,
            new
            {
                CategoryID = categoryId,
                request.CategoryName,
                request.CategoryNameNotVietkey,
                request.CategoryLink,
                request.ParentCategoryID,
                request.Level,
                request.NodeTree,
                request.Description,
                request.IsDefault,
                request.IsActived,
                request.IsShowGroupInHome,
                request.OrderIndex,
                request.CategoryNameEn,
                request.CategoryLinkEn,
                request.DescriptionEn,
                request.SpecialShow,
                request.IsShowGroupInFooter,
                request.CategoryNameLang3,
                request.CategoryLinkLang3,
                request.DescriptionLang3,
                request.ItemCount,
                request.UpdatedUser
            },
            cancellationToken);
    }

    public async Task<int> DeleteAsync(
        long categoryId,
        string deletedUser,
        CancellationToken cancellationToken = default)
    {
        return await ExecuteScalarAsync<int>(
            StoredProcedureNames.Category.Delete,
            new { CategoryID = categoryId, DeletedUser = deletedUser },
            cancellationToken);
    }

    private static CategoryResponseDto MapToResponse(CategoryListItemDto item)
    {
        return new CategoryResponseDto
        {
            CategoryID = item.CategoryID,
            CategoryName = item.CategoryName,
            CategoryNameNotVietkey = item.CategoryNameNotVietkey,
            CategoryLink = item.CategoryLink,
            ParentCategoryID = item.ParentCategoryID,
            Level = item.Level,
            NodeTree = item.NodeTree,
            Description = item.Description,
            IsDefault = item.IsDefault,
            IsActived = item.IsActived,
            IsShowGroupInHome = item.IsShowGroupInHome,
            IsShowGroupInFooter = item.IsShowGroupInFooter,
            OrderIndex = item.OrderIndex,
            SpecialShow = item.SpecialShow,
            ItemCount = item.ItemCount,
            CategoryNameEn = item.CategoryNameEn,
            CategoryLinkEn = item.CategoryLinkEn,
            DescriptionEn = item.DescriptionEn,
            CategoryNameLang3 = item.CategoryNameLang3,
            CategoryLinkLang3 = item.CategoryLinkLang3,
            DescriptionLang3 = item.DescriptionLang3,
            CreatedDate = item.CreatedDate,
            CreatedUser = item.CreatedUser,
            UpdatedDate = item.UpdatedDate,
            UpdatedUser = item.UpdatedUser
        };
    }
}

