namespace _2026WebAPI_01.Services;

public sealed class CategoryService : ICategoryService
{
    private readonly ICategoryRepository _categoryRepository;

    public CategoryService(ICategoryRepository categoryRepository)
    {
        _categoryRepository = categoryRepository;
    }

    public async Task<ApiResponse<PagedResult<CategoryResponseDto>>> SearchAsync(
        CategorySearchRequest request,
        CancellationToken cancellationToken = default)
    {
        var result = await _categoryRepository.SearchAsync(request, cancellationToken);

        return ApiResponse<PagedResult<CategoryResponseDto>>.Ok(
            result,
            ApiMessages.Success,
            totalRecords: result.TotalRecords);
    }

    public async Task<ApiResponse<CategoryResponseDto>> GetByIdAsync(
        long categoryId,
        CancellationToken cancellationToken = default)
    {
        var category = await _categoryRepository.GetByIdAsync(categoryId, cancellationToken);

        if (category is null)
        {
            return ApiResponse<CategoryResponseDto>.Fail(
                ApiMessages.NotFound,
                StatusCodes.Status404NotFound);
        }

        return ApiResponse<CategoryResponseDto>.Ok(
            category,
            ApiMessages.Success,
            totalRecords: 1);
    }

    public async Task<ApiResponse<CategoryResponseDto>> CreateAsync(
        CategoryCreateRequest request,
